# -*- coding: utf-8 -*-\n\"\"\"\nGenerador de Chistes Aleatorios usando JokeAPI\nAplicación Streamlit que consume una API externa para obtener chistes\n\"\"\"\n\nimport streamlit as st\nimport requests\nimport json\nfrom typing import Dict, Optional\nimport logging\n\n# Configuración de logging\nlogging.basicConfig(level=logging.INFO)\nlogger = logging.getLogger(__name__)\n\n# Configuración de la página\nst.set_page_config(\n    page_title=\"😄 Random Joke Generator\",\n    page_icon=\"😄\",\n    layout=\"centered\"\n)\n\n# Estilos\nst.markdown(\"\"\"\n    <style>\n    .joke-container {\n        background-color: #f0f8ff;\n        padding: 20px;\n        border-radius: 10px;\n        border-left: 5px solid #1f77e6;\n        margin: 20px 0;\n    }\n    .joke-text {\n        font-size: 18px;\n        font-style: italic;\n        color: #333;\n    }\n    .joke-punchline {\n        font-size: 16px;\n        font-weight: bold;\n        color: #1f77e6;\n        margin-top: 15px;\n    }\n    </style>\n\"\"\")\n\n# URL de la API\nJOKE_API_URL = \"https://jokeapi.dev/joke\"\n\ndef get_random_joke(category: str = \"Any\") -> Optional[Dict]:\n    \"\"\"\n    Obtiene un chiste aleatorio de la API.\n    \n    Args:\n        category: Categoría de chiste (Any, Programming, Knock-knock, etc.)\n        \n    Returns:\n        Diccionario con datos del chiste o None si hay error\n    \"\"\"\n    try:\n        params = {\n            \"format\": \"json\",\n            \"lang\": \"es\"  # Español\n        }\n        \n        url = f\"{JOKE_API_URL}/{category}\"\n        response = requests.get(url, params=params, timeout=5)\n        response.raise_for_status()\n        \n        data = response.json()\n        logger.info(f\"Chiste obtenido: {category}\")\n        return data\n        \n    except requests.exceptions.RequestException as e:\n        logger.error(f\"Error al obtener chiste: {str(e)}\")\n        return None\n\n# Interfaz\nst.title(\"😄 Generador de Chistes Aleatorios\")\nst.markdown(\"---\")\nst.write(\"Haz clic en el botón para obtener un chiste aleatorio de la API [JokeAPI](https://jokeapi.dev/)\")\n\n# Sidebar\nwith st.sidebar:\n    st.header(\"⚙️ Configuración\")\n    \n    categorias = {\n        \"🎯 Cualquiera\": \"Any\",\n        \"💻 Programación\": \"Programming\",\n        \"🚪 Golpe a la Puerta\": \"Knock-knock\",\n        \"😂 General\": \"General\",\n        \"⚪ Otro\": \"Misc\"\n    }\n    \n    categoria_selected = st.selectbox(\"Elige una categoría:\", list(categorias.keys()))\n    categoria_api = categorias[categoria_selected]\n    \n    st.markdown(\"---\")\n    st.info(\"💡 Usa la categoría 'Cualquiera' para obtener chistes variados\")\n\n# Contenido principal\nif st.button(\"🎲 Generar Chiste\", use_container_width=True, type=\"primary\"):\n    with st.spinner(\"Buscando un chiste divertido...\"):\n        joke_data = get_random_joke(categoria_api)\n        \n        if joke_data and joke_data.get(\"error\") is False:\n            st.markdown(\"<div class='joke-container'>\", unsafe_allow_html=True)\n            \n            if joke_data.get(\"type\") == \"single\":\n                # Chiste de una línea\n                st.markdown(f\"<p class='joke-text'>{joke_data.get('joke', '')}</p>\", unsafe_allow_html=True)\n            else:\n                # Chiste de dos partes\n                st.markdown(f\"<p class='joke-text'>{joke_data.get('setup', '')}</p>\", unsafe_allow_html=True)\n                st.markdown(f\"<p class='joke-punchline'>{joke_data.get('delivery', '')}</p>\", unsafe_allow_html=True)\n            \n            st.markdown(\"</div>\", unsafe_allow_html=True)\n            \n            # Información adicional\n            col1, col2 = st.columns(2)\n            with col1:\n                st.caption(f\"Categoría: {joke_data.get('category', 'N/A')}\")\n            with col2:\n                if joke_data.get('flags', {}).get('explicit'):\n                    st.caption(\"⚠️ Contenido explícito\")\n        else:\n            st.error(\"❌ No se pudo obtener un chiste. Intenta de nuevo.\")\n\n# Historial (usando session state)\nif \"historial\" not in st.session_state:\n    st.session_state.historial = []\n\nwith st.expander(\"📜 Historial de Chistes\"):\n    if st.session_state.historial:\n        for i, chiste in enumerate(st.session_state.historial, 1):\n            st.write(f\"{i}. {chiste}\")\n        \n        if st.button(\"🗑️ Limpiar historial\"):\n            st.session_state.historial = []\n            st.success(\"Historial limpiado\")\n    else:\n        st.write(\"El historial está vacío. ¡Genera algunos chistes!\")\n\nst.markdown(\"---\")\nst.markdown(\"\"\"\n    <div style='text-align: center; color: #666; font-size: 12px;'>\n        Powered by <a href='https://jokeapi.dev/'>JokeAPI</a> | Streamlit App<br>\n        Desarrollado con ❤️ por Blanca\n    </div>\n\"\"\", unsafe_allow_html=True)\n